package com.example.domain.model.i18n

internal object DuaTa3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_against_enemy_ahzab" to DuaText("எதிரிப் படைகளுக்கு எதிராக", "யா அல்லாஹ்! வேதத்தை இறக்கியவனே, விரைவாகக் கணக்கெடுப்பவனே! இந்தப் படைகளைத் தோற்கடிப்பாயாக. யா அல்லாஹ்! அவர்களைத் தோற்கடித்து, அவர்களை நிலைகுலையச் செய்வாயாக.", "எதிரியை எதிர்கொள்ளும்போது — அஹ்ஸாப் போரின் துஆ.", "எதிரிக்கு எதிராக நபி ﷺ அவர்கள் செய்த துஆ."),
        "dua_ahsin_aqibatana" to DuaText("எல்லாக் காரியங்களிலும் நல்ல முடிவு", "யா அல்லாஹ்! எல்லாக் காரியங்களிலும் எங்கள் முடிவை நல்லதாக்குவாயாக; இவ்வுலக இழிவிலிருந்தும் மறுமையின் வேதனையிலிருந்தும் எங்களைப் பாதுகாப்பாயாக.", "ஒவ்வொரு காரியத்திலும் நல்ல முடிவுக்காக.", "இந்த துஆவைச் செய்பவர் சோதனைக்கு முன் மரணித்தால் (சோதனையிலிருந்து பாதுகாப்பாக) மரணிக்கிறார்."),
        "dua_ahyini_ma_kanat" to DuaText("மரணத்தை விரும்புவதற்குப் பதிலாக", "யா அல்லாஹ்! வாழ்வு எனக்குச் சிறந்ததாக இருக்கும் வரை என்னை வாழ வைப்பாயாக; மரணம் எனக்குச் சிறந்ததாக இருக்கும்போது என்னை மரணிக்கச் செய்வாயாக.", "கஷ்டத்தில் மரணத்தை விரும்புவதற்குப் பதிலாக.", "நபி ﷺ அவர்கள் மரணத்தை விரும்புவதைத் தடுத்து, அதற்குப் பதிலாக இதைக் கற்றுக்கொடுத்தார்கள்."),
        "dua_ajz_kasal_haram" to DuaText("இயலாமையிலிருந்தும் முதுமையிலிருந்தும் பாதுகாப்பு", "யா அல்லாஹ்! இயலாமை மற்றும் சோம்பலிலிருந்தும், கோழைத்தனம் மற்றும் முதுமையிலிருந்தும், வாழ்வு மற்றும் மரணத்தின் சோதனையிலிருந்தும், கப்ரின் வேதனையிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன்.", "அன்றாடம் ஓதும் விரிவான பாதுகாப்பு துஆ.", "நபி ﷺ அவர்கள் அடிக்கடி செய்த துஆ."),
        "dua_ala_kulli_hal" to DuaText("எல்லா நிலையிலும் புகழ்", "எல்லா நிலையிலும் அல்லாஹ்வுக்கே எல்லாப் புகழும்.", "விரும்பாத ஒன்று நிகழும்போது.", "விரும்பாத ஒன்றை எதிர்கொள்ளும்போது நபி ﷺ அவர்கள் இதைக் கூறுவார்கள்."),
        "dua_allahu_akbar_kabira_2696" to DuaText("கிராமவாசிக்குக் கற்றுக்கொடுத்த வார்த்தைகள்", "அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை; அவன் தனித்தவன், அவனுக்கு இணையில்லை. அல்லாஹ் மிகப் பெரியவன்; அல்லாஹ்வுக்கே அதிகமான புகழ்; அகிலங்களின் இறைவனான அல்லாஹ் தூயவன்; மிகைத்தவனும் ஞானமிக்கவனுமான அல்லாஹ்வைக் கொண்டே தவிர (பாவத்திலிருந்து விலகும்) ஆற்றலும் (நன்மை செய்யும்) வலிமையும் இல்லை.", "திக்ரும் துஆவும் இணைந்த விரிவான வார்த்தைகள் — ஒரு கிராமவாசிக்குக் கற்றுக்கொடுக்கப்பட்டது.", "இதன் பிறகு 'அல்லாஹும்மஃக்ஃபிர் லீ வர்ஹம்னீ வஹ்தினீ வர்ஸுக்னீ' என்று கூறுமாறு கற்றுக்கொடுக்கப்பட்டது."),
        "dua_anta_adudi" to DuaText("நீயே என் துணை", "யா அல்லாஹ்! நீயே என் துணையும் என் உதவியாளனும் ஆவாய். உன்னைக் கொண்டே திட்டமிடுகிறேன், உன்னைக் கொண்டே முன்னேறுகிறேன், உன்னைக் கொண்டே போராடுகிறேன்.", "போட்டி அல்லது பெரிய சவாலுக்கு முன்.", "நபி ﷺ அவர்கள் போரின்போது இதைக் கூறுவார்கள்."),
        "dua_ascending_descending" to DuaText("ஏறும்போதும் இறங்கும்போதும்", "அல்லாஹ் மிகப் பெரியவன் (மேலே ஏறும்போது). — அல்லாஹ் தூயவன் (கீழே இறங்கும்போது).", "பயணத்தில் மேலே ஏறும்போது 'அல்லாஹு அக்பர்' என்றும், கீழே இறங்கும்போது 'ஸுப்ஹானல்லாஹ்' என்றும் கூறுங்கள்.", "பயணத்தின்போது ஸஹாபாக்களின் (ரலி) நடைமுறை."),
        "dua_aslih_li_dini" to DuaText("என் மார்க்கம், உலகம், மறுமையைச் சீராக்கு", "யா அல்லாஹ்! என் எல்லாக் காரியங்களுக்கும் பாதுகாப்பான என் மார்க்கத்தைச் சீராக்குவாயாக; என் வாழ்வாதாரம் உள்ள என் உலக வாழ்க்கையைச் சீராக்குவாயாக; நான் திரும்பிச் செல்ல வேண்டிய என் மறுமையைச் சீராக்குவாயாக. வாழ்வை எனக்கு எல்லா நன்மையிலும் அதிகரிப்பாக்குவாயாக, மரணத்தை எல்லாத் தீமையிலிருந்தும் எனக்கு ஓய்வாக்குவாயாக.", "மார்க்கம், இவ்வுலகம், மறுமை — மூன்றையும் சீராக்குதல்.", "நபி ﷺ அவர்களின் விரிவான துஆ."),
        "dua_ati_nafsi_taqwaha" to DuaText("என் ஆன்மாவுக்கு அதன் இறையச்சத்தைக் கொடு", "யா அல்லாஹ்! என் ஆன்மாவுக்கு அதன் இறையச்சத்தை (தக்வா) வழங்கி அதைத் தூய்மைப்படுத்துவாயாக; அதைத் தூய்மைப்படுத்துவோரில் நீயே சிறந்தவன். நீயே அதன் பாதுகாவலனும் அதிபதியும் ஆவாய்.", "ஆன்மாவைச் சீராக்கித் தூய்மைப்படுத்துவதற்காக.", "நபி ﷺ அவர்கள் இந்த துஆவைச் செய்து வந்தார்கள்."),
        "dua_being_praised" to DuaText("உங்களைப் புகழும்போது", "யா அல்லாஹ்! அவர்கள் கூறுவதற்காக என்னைக் குற்றம் பிடிக்காதே; அவர்கள் அறியாத என் பாவங்களை மன்னிப்பாயாக.", "தம்மைப் பிறர் புகழக் கேட்கும்போது — ஒரு ஸஹாபியின் (ரலி) நடைமுறை.", "புகழப்படும்போது பெருமையிலிருந்து தப்பிக்கும் வழி."),
        "dua_bi_ilmikal_ghayb" to DuaText("வாழ்வு சிறந்ததாக இருக்கும் வரை வாழ வை", "யா அல்லாஹ்! மறைவானவற்றைப் பற்றிய உன் அறிவையும், படைப்புகள் மீதான உன் ஆற்றலையும் முன்னிட்டு — வாழ்வு எனக்குச் சிறந்தது என்று நீ அறியும் வரை என்னை வாழ வைப்பாயாக, மரணம் எனக்குச் சிறந்தது என்று நீ அறியும்போது என்னை மரணிக்கச் செய்வாயாக. யா அல்லாஹ்! மறைவிலும் வெளிப்படையிலும் உன்னைப் பற்றிய அச்சத்தையும், திருப்தியிலும் கோபத்திலும் சத்திய வார்த்தையையும், வறுமையிலும் செல்வத்திலும் நடுநிலையையும் உன்னிடம் கேட்கிறேன்.", "அம்மார் இப்னு யாஸிர் (ரலி) அவர்களின் தொழுகை துஆ (தொடக்கப் பகுதி).", "நபி ﷺ அவர்கள் தொழுகையில் இந்த துஆவைச் செய்வார்கள்."),
        "dua_dogs_barking" to DuaText("இரவில் நாய்கள் குரைப்பதைக் கேட்கும்போது", "விரட்டப்பட்ட ஷைத்தானை விட்டும் அல்லாஹ்விடம் பாதுகாப்புத் தேடுகிறேன்.", "இரவில் நாய்கள் குரைப்பதையோ கழுதை கத்துவதையோ கேட்கும்போது.", "நீங்கள் பார்க்காதவற்றை அவை பார்க்கின்றன."),
        "dua_eid_greeting" to DuaText("பெருநாள் வாழ்த்து", "அல்லாஹ் எங்களிடமிருந்தும் உங்களிடமிருந்தும் (நற்செயல்களை) ஏற்றுக்கொள்வானாக.", "பெருநாள் அன்று ஒருவருக்கொருவர் — கண்ணியமிக்க ஸஹாபாக்களின் (ரலி) நடைமுறை.", "ஸஹாபாக்கள் பெருநாளில் சந்திக்கும்போது இதைக் கூறுவார்கள்."),
        "dua_eid_takbeer" to DuaText("ஈத்காஹ் செல்லும்போது தக்பீர்", "அல்லாஹ் மிகப் பெரியவன், அல்லாஹ் மிகப் பெரியவன், அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை; அல்லாஹ் மிகப் பெரியவன், அல்லாஹ் மிகப் பெரியவன், அல்லாஹ்வுக்கே எல்லாப் புகழும்.", "பிறை பார்த்த இரவு முதல் ஈதுல் ஃபித்ர் தொழுகை வரை, குறிப்பாக ஈத்காஹ் செல்லும் வழியில்.", "குர்ஆனின் கட்டளை: 'நீங்கள் எண்ணிக்கையை நிறைவு செய்து, அல்லாஹ்வின் பெருமையைப் போற்றுவதற்காக' (அல்-பகரா 2:185). இப்னு மஸ்ஊத் (ரலி) இந்தத் தக்பீரைக் கூறுவார்கள்."),
        "dua_entering_village" to DuaText("ஊர் அல்லது நகரத்தில் நுழையும்போது", "யா அல்லாஹ்! ஏழு வானங்களுக்கும் அவை நிழலிடுபவற்றுக்கும் இறைவனே, ஏழு பூமிகளுக்கும் அவை சுமப்பவற்றுக்கும் இறைவனே, ஷைத்தான்களுக்கும் அவை வழிகெடுத்தவர்களுக்கும் இறைவனே, காற்றுகளுக்கும் அவை சிதறடிப்பவற்றுக்கும் இறைவனே! இந்த ஊரின் நன்மையையும் இதன் மக்களின் நன்மையையும் உன்னிடம் கேட்கிறோம்; இதன் தீமையிலிருந்தும், இதன் மக்களின் தீமையிலிருந்தும், இதிலுள்ளவற்றின் தீமையிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறோம்.", "ஒரு ஊர்/நகரத்தில் நுழைவதற்கு முன்.", "நபி ﷺ அவர்கள் எந்த ஊரில் நுழைய விரும்பினாலும் இதை ஓதுவார்கள்."),
        "dua_evening_blessing" to DuaText("மாலை நேர அருட்கொடைகளுக்கு நன்றி", "யா அல்லாஹ்! இந்த மாலையில் எனக்கோ உன் படைப்புகளில் எவருக்கோ கிடைத்த எந்த அருட்கொடையும் உன்னிடமிருந்து மட்டுமே; உனக்கு இணையில்லை. எனவே எல்லாப் புகழும் உனக்கே, எல்லா நன்றியும் உனக்கே.", "அல்லாஹ்வின் அருட்கொடைகளுக்காக நன்றி செலுத்தும் மாலை திக்ர்."),
        "dua_evening_witness" to DuaText("மாலை நேர ஏகத்துவச் சாட்சி", "யா அல்லாஹ்! நான் மாலைப் பொழுதை அடைந்தேன்; நீயே அல்லாஹ், உன்னைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை, நீ தனித்தவன், உனக்கு இணையில்லை, முஹம்மது ﷺ உன் அடியாரும் தூதருமாவார்கள் என்பதற்கு உன்னையும், உன் அர்ஷைச் சுமப்பவர்களையும், உன் வானவர்களையும், உன் எல்லாப் படைப்புகளையும் சாட்சியாக்குகிறேன்.", "மாலையில் இதை நான்கு முறை கூறுவதாக அறிவிப்பில் உள்ளது."),
        "dua_fadlika_wa_rahmatik" to DuaText("உன் அருளையும் கருணையையும் கேட்டல்", "யா அல்லாஹ்! உன் அருளையும் (ஃபள்ல்) உன் கருணையையும் உன்னிடம் கேட்கிறேன்; அவற்றை உன்னைத் தவிர வேறு யாரும் உடைமையாக்கவில்லை.", "ரிஸ்கையும் கருணையையும் கேட்கும்போது.", "உணவு இல்லாத நேரத்தில் நபி ﷺ அவர்களிடம் விருந்தினர்கள் வந்தனர்; அவர்கள் இந்த துஆவைச் செய்தார்கள், பின்னர் ஓர் அன்பளிப்பு வந்தது."),
        "dua_faqr_qillah_dhillah" to DuaText("வறுமை மற்றும் இழிவிலிருந்து பாதுகாப்பு", "யா அல்லாஹ்! வறுமை, பற்றாக்குறை, இழிவு ஆகியவற்றிலிருந்தும், நான் அநீதி இழைப்பதிலிருந்தும் எனக்கு அநீதி இழைக்கப்படுவதிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன்.", "கஷ்டம், பற்றாக்குறை, இழிவு ஆகியவற்றிலிருந்து பாதுகாப்பாக இருக்க.", "நபி ﷺ அவர்கள் கற்றுக்கொடுத்த பாதுகாப்பு துஆ."),
        "dua_fasting_invited" to DuaText("நோன்பின்போது விருந்துக்கு அழைக்கப்பட்டால்", "நான் நோன்பாளி.", "நோன்பிருக்கும்போது விருந்துக்கு அழைக்கப்பட்டால் அல்லது யாரேனும் சண்டையிட்டால்.", "நோன்பாளி அழைப்பை ஏற்றுக்கொண்டால், விருந்தளிப்பவருக்காக துஆ செய்யட்டும்."),
        "dua_filal_khayrat" to DuaText("நன்மைகள் செய்தலும் தீமைகளை விடுதலும்", "யா அல்லாஹ்! நன்மைகள் செய்வதையும், தீமைகளை விட்டுவிடுவதையும், ஏழைகளை நேசிப்பதையும், நீ என்னை மன்னித்து எனக்குக் கருணை காட்டுவதையும் உன்னிடம் கேட்கிறேன். ஒரு கூட்டத்தினரைச் சோதனைக்கு உள்ளாக்க நீ நாடினால், சோதனைக்கு உள்ளாகாத நிலையில் என்னைக் கைப்பற்றிக்கொள்வாயாக. உன் அன்பையும், உன்னை நேசிப்பவர்களின் அன்பையும், உன் அன்பின் பக்கம் என்னை நெருக்கமாக்கும் செயல்களின் அன்பையும் உன்னிடம் கேட்கிறேன்.", "கனவில் அல்லாஹ் இந்த துஆவை நபி ﷺ அவர்களுக்குக் கற்றுக்கொடுத்தான்.", "நபி ﷺ அவர்கள் கூறினார்கள்: இது உண்மையானது, இதைக் கற்றுக்கொள்ளுங்கள், கற்றுக்கொடுங்கள்."),
        "dua_fitnat_ghina_faqr" to DuaText("செல்வம் மற்றும் வறுமையின் சோதனையிலிருந்து பாதுகாப்பு", "யா அல்லாஹ்! சோம்பல் மற்றும் முதுமையிலிருந்தும், பாவம் மற்றும் கடனிலிருந்தும், கப்ரின் சோதனை மற்றும் வேதனையிலிருந்தும், நரகத்தின் சோதனை மற்றும் வேதனையிலிருந்தும், செல்வத்தின் சோதனையின் தீமையிலிருந்தும், வறுமையின் சோதனையிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன்.", "கப்ர், நரகம், செல்வம், வறுமை ஆகியவற்றின் சோதனைகளிலிருந்து பாதுகாப்பு (துஆவின் ஒரு பகுதி).", "நபி ﷺ அவர்களின் விரிவான பாதுகாப்பு துஆ."),
        "dua_five_things_new_muslim" to DuaText("மன்னிப்பு, கருணை, நேர்வழி, நலன், ரிஸ்க்", "யா அல்லாஹ்! என்னை மன்னிப்பாயாக, எனக்குக் கருணை காட்டுவாயாக, எனக்கு நேர்வழி காட்டுவாயாக, எனக்கு நலன் அளிப்பாயாக, எனக்கு ரிஸ்க் அளிப்பாயாக.", "புதிதாக இஸ்லாத்தை ஏற்றவர்களுக்கு நபி ﷺ அவர்கள் தொழுகையுடன் இந்த துஆவையும் கற்றுக்கொடுப்பார்கள்.", "நபி ﷺ அவர்கள் கூறினார்கள்: இந்த வார்த்தைகள் உனக்கு இம்மையையும் மறுமையையும் ஒன்றுசேர்க்கின்றன."),
        "dua_for_one_i_cursed" to DuaText("வார்த்தைகளால் புண்படுத்தியவருக்காக", "யா அல்லாஹ்! நான் திட்டிய எந்த முஃமினுக்கும், அதை மறுமை நாளில் உன் பக்கம் அவருக்கு நெருக்கத்தை ஏற்படுத்தும் வழியாக ஆக்குவாயாக.", "கோபத்தில் யாரையேனும் திட்டிவிட்டால் அவருக்காக.", "நபி ﷺ அவர்களின் துஆ."),
        "dua_for_who_gave_drink" to DuaText("உணவளித்தவருக்காகவும் பானம் அளித்தவருக்காகவும்", "யா அல்லாஹ்! எனக்கு உணவளித்தவருக்கு நீ உணவளிப்பாயாக, எனக்குப் பானம் அளித்தவருக்கு நீ பானம் அளிப்பாயாக.", "உணவோ பானமோ அளிப்பவருக்காக.", "நபி ﷺ அவர்கள் மிக்தாத் (ரலி) அவர்களுக்காக இந்த துஆவைச் செய்தார்கள்."),
        "dua_ghalabatid_dayn" to DuaText("கடன் சுமை மற்றும் எதிரிகளிலிருந்து பாதுகாப்பு", "யா அல்லாஹ்! கடனால் மிகைக்கப்படுவதிலிருந்தும், எதிரியால் அடக்கப்படுவதிலிருந்தும், எதிரிகள் மகிழ்வதிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன்.", "கடன் சுமையிலிருந்தும் எதிரிகளின் ஆதிக்கத்திலிருந்தும் பாதுகாப்பு.", "நபி ﷺ அவர்கள் இவற்றிலிருந்து பாதுகாப்புத் தேடுவார்கள்."),
        "dua_hadm_gharaq" to DuaText("திடீர் மரணம் மற்றும் விபத்துகளிலிருந்து பாதுகாப்பு", "யா அல்லாஹ்! (கட்டடம்) இடிந்து விழுவதிலிருந்தும், உயரத்திலிருந்து விழுவதிலிருந்தும், நீரில் மூழ்குவதிலிருந்தும், தீயில் எரிவதிலிருந்தும், முதுமையிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன்; மரண நேரத்தில் ஷைத்தான் என்னை வழிகெடுப்பதிலிருந்தும், உன் பாதையில் புறமுதுகிட்டு ஓடும் நிலையில் மரணிப்பதிலிருந்தும், (விஷ ஜந்து) கொட்டி மரணிப்பதிலிருந்தும் (பாதுகாப்புத் தேடுகிறேன்).", "விபத்துகள் மற்றும் கெட்ட மரணத்திலிருந்து பாதுகாப்பு.", "நபி ﷺ அவர்களின் பாதுகாப்பு துஆ."),
        "dua_hajj_la_riya" to DuaText("முகஸ்துதியற்ற ஹஜ்", "யா அல்லாஹ்! முகஸ்துதியும் புகழ் தேடலும் இல்லாத ஹஜ்ஜாக (ஆக்குவாயாக).", "ஹஜ்ஜுக்கு நிய்யத் செய்யும்போது உளத்தூய்மைக்காக.", "நபி ﷺ அவர்கள் ஹஜ்ஜின்போது இந்த துஆவைச் செய்தார்கள்."),
        "dua_hubbaka" to DuaText("அல்லாஹ்வின் அன்பைக் கேட்டல்", "யா அல்லாஹ்! உன் அன்பையும், உன்னை நேசிப்பவர்களின் அன்பையும், உன் அன்பின் பக்கம் என்னைச் சேர்க்கும் செயல்களையும் உன்னிடம் கேட்கிறேன். யா அல்லாஹ்! உன் அன்பை என்னையும், என் குடும்பத்தையும், குளிர்ந்த நீரையும் விட எனக்கு அதிக விருப்பமானதாக ஆக்குவாயாக.", "நபி ﷺ அவர்கள் அறிவித்த தாவூத் (அலை) அவர்களின் துஆ.", "அல்லாஹ்வின் அன்பே மிகப் பெரிய செல்வம்."),
        "dua_huda_tuqa" to DuaText("நேர்வழி, இறையச்சம், கற்பொழுக்கம், தன்னிறைவு", "யா அல்லாஹ்! நேர்வழியையும், இறையச்சத்தையும், கற்பொழுக்கத்தையும், (பிறரிடம் தேவையற்ற) தன்னிறைவையும் உன்னிடம் கேட்கிறேன்.", "நபி ﷺ அவர்களின் சுருக்கமான, விரிவான பொருள் கொண்ட துஆ.", "மார்க்கம் மற்றும் உலகின் நான்கு அடிப்படை அருட்கொடைகள்."),
        "dua_iftar_ibn_umar" to DuaText("இஃப்தார் — உன் விசாலமான கருணையால் என்னை மன்னி", "யா அல்லாஹ்! எல்லாவற்றையும் சூழ்ந்துள்ள உன் கருணையைக் கொண்டு, நீ என்னை மன்னிக்குமாறு உன்னிடம் கேட்கிறேன்.", "இஃப்தார் நேரத்தில் — அப்துல்லாஹ் இப்னு அம்ர் (ரலி) இந்த துஆவைச் செய்வார்கள்; இஃப்தாரின்போது நோன்பாளியின் துஆ மறுக்கப்படுவதில்லை.", "ஹதீஸ்: இஃப்தார் நேரத்தில் நோன்பாளியின் துஆ மறுக்கப்படுவதில்லை."),
        "dua_iftar_laka_sumtu" to DuaText("இஃப்தார் — உனக்காக நோன்பு நோற்றேன்", "யா அல்லாஹ்! உனக்காகவே நோன்பு நோற்றேன், நீ அளித்த உணவைக் கொண்டே நோன்பு திறக்கிறேன்.", "நோன்பு திறக்கும்போது (பிரபலமான இஃப்தார் துஆ).", "நபி ﷺ அவர்கள் இஃப்தாரின்போது இதைக் கூறுவார்கள். இது பிற அறிவிப்புகளால் வலுப்பெறும் முர்ஸல் அறிவிப்பு; இஃப்தாரில் இதை ஓதுவது ஹனஃபீகள் மற்றும் பெரும்பான்மை அறிஞர்களின் நடைமுறை."),
        "dua_ihdini_saddidni" to DuaText("எனக்கு நேர்வழி காட்டி, நேராக வைத்திரு", "யா அல்லாஹ்! எனக்கு நேர்வழி காட்டுவாயாக, என்னைச் சரியான பாதையில் நிலைநிறுத்துவாயாக.", "நபி ﷺ அவர்கள் அலீ (ரலி) அவர்களுக்குக் கற்றுக்கொடுத்தார்கள்.", "நேர்வழியைச் சாலையில் வழிகாட்டப்படுவதாகவும், 'ஸதாத்' ஐ அம்பின் நேர்த்தியாகவும் நினைத்துக்கொள்."),
        "dua_ikfinihim" to DuaText("அவர்களுக்கு எதிராக எனக்குப் போதுமானவனாக இரு", "யா அல்லாஹ்! நீ நாடிய விதத்தில் அவர்களுக்கு எதிராக எனக்குப் போதுமானவனாக இருப்பாயாக.", "அநியாயக்காரர்களின் தீங்கிலிருந்து — அகழ்வாசிகள் (அஸ்ஹாபுல் உக்தூத்) நிகழ்வில் வரும் சிறுவனின் துஆ.", "அல்லாஹ் அந்தச் சிறுவனை அநியாயக்காரர்களிடமிருந்து காப்பாற்றினான்."),
        "dua_ilbas_jadidan" to DuaText("ஒருவரைப் புதிய ஆடையில் காணும்போது", "புதியதை அணிவீராக, புகழுக்குரிய வாழ்க்கை வாழ்வீராக, ஷஹீதாக மரணிப்பீராக.", "ஒரு முஸ்லிம் சகோதரரைப் புதிய ஆடையில் காணும்போது.", "உமர் (ரலி) அவர்களைப் புதிய ஆடையில் கண்டபோது நபி ﷺ அவர்கள் இந்த துஆவைச் செய்தார்கள்."),
        "dua_infani_bima_allamtani" to DuaText("கற்றுக்கொடுத்ததைக் கொண்டு பயனளி", "யா அல்லாஹ்! நீ எனக்குக் கற்றுக்கொடுத்ததைக் கொண்டு எனக்குப் பயனளிப்பாயாக, எனக்குப் பயனளிப்பதைக் கற்றுக்கொடுப்பாயாக, என் அறிவை அதிகப்படுத்துவாயாக.", "அறிவைத் தேடும்போது அல்லது படிப்பதற்கு முன்.", "பயனுள்ள அறிவுக்காகவும் அதன்படி செயல்படுவதற்காகவும் துஆ."),
        "dua_inni_saim" to DuaText("நோன்பின்போது யாரேனும் தூண்டினால்", "நான் நோன்பாளி, நான் நோன்பாளி.", "நோன்பிருக்கும்போது யாரேனும் திட்டினால் அல்லது சண்டையிட்டால்.", "நபி ﷺ அவர்கள் கூறினார்கள்: நோன்பு ஒரு கேடயம்; எனவே நோன்பாளி ஆபாசமாகப் பேசவோ அறிவீனமாக நடக்கவோ வேண்டாம் — யாரேனும் சண்டையிட்டால் இதை இரண்டு முறை கூறட்டும்."),
        "dua_iqsim_lana_khashyatik" to DuaText("உன்னைப் பற்றிய அச்சத்தை எங்களுக்குப் பங்கிடு", "யா அல்லாஹ்! எங்களுக்கும் உனக்கு மாறுசெய்வதற்கும் இடையே தடையாக இருக்கும் அளவுக்கு உன்னைப் பற்றிய அச்சத்தையும், உன் சுவர்க்கத்துக்கு எங்களைச் சேர்க்கும் அளவுக்கு உனக்குக் கீழ்ப்படிதலையும், இவ்வுலகச் சோதனைகளை எங்களுக்கு எளிதாக்கும் அளவுக்கு உறுதியான நம்பிக்கையையும் எங்களுக்குப் பங்கிடுவாயாக. நீ எங்களை வாழ வைக்கும் வரை எங்கள் செவிப்புலன், பார்வை, வலிமை ஆகியவற்றால் எங்களுக்குப் பயனளிப்பாயாக, அவற்றை எங்களுக்குப் பின்னும் நிலைத்திருக்கச் செய்வாயாக. எங்களுக்கு அநீதி இழைப்பவர்களிடம் எங்களுக்காகப் பழிவாங்குவாயாக, எங்கள் எதிரிகளுக்கு எதிராக எங்களுக்கு உதவுவாயாக, எங்கள் சோதனையை எங்கள் மார்க்கத்தில் ஆக்காதே, இவ்வுலகை எங்கள் மிகப் பெரிய கவலையாகவோ எங்கள் அறிவின் எல்லையாகவோ ஆக்காதே, எங்களிடம் கருணை காட்டாதவர்களை எங்கள் மீது ஆதிக்கம் செலுத்த வைக்காதே.", "சபையிலிருந்து எழும்போது — நபி ﷺ அவர்கள் இந்த துஆவைச் செய்யாமல் அரிதாகவே எழுவார்கள்.", "மார்க்கம், இவ்வுலகம், மறுமை ஆகியவற்றின் நன்மைக்கான விரிவான துஆ."),
        "dua_ishfi_abdak" to DuaText("நோயாளியின் குணத்துக்காக", "யா அல்லாஹ்! உன் அடியாருக்குக் குணமளிப்பாயாக; அவர் உனக்காக எதிரியை எதிர்கொள்வார், அல்லது உனக்காகத் தொழுகைக்கு நடந்து செல்வார்.", "நோயாளியை நலம் விசாரிக்கச் செல்லும்போது அவருக்காக.", "நபி ﷺ அவர்கள் நோயாளிக்காக இதைக் கூறுமாறு கற்றுக்கொடுத்தார்கள்."),
        "dua_ism_azam_ahad_samad" to DuaText("இஸ்முல் அஃளம்: அல்-அஹத், அஸ்-ஸமத்", "யா அல்லாஹ்! நீயே அல்லாஹ் என்று நான் சாட்சி கூறுவதைக் கொண்டு உன்னிடம் கேட்கிறேன்; உன்னைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை; நீ ஏகன், தேவையற்றவன்; அவன் யாரையும் பெறவில்லை, யாராலும் பெறப்படவில்லை; அவனுக்கு நிகராக எவருமில்லை.", "இந்த மனிதர் அல்லாஹ்வின் மகத்தான பெயரைக் கொண்டு கேட்டார் என்று நபி ﷺ அவர்கள் கூறினார்கள்.", "இதைக் கொண்டு கேட்டால் அவன் கொடுக்கிறான்; இதைக் கொண்டு அழைத்தால் அவன் பதிலளிக்கிறான்."),
        "dua_ism_azam_mannan" to DuaText("இஸ்முல் அஃளம்: அல்-மன்னான்", "யா அல்லாஹ்! எல்லாப் புகழும் உனக்கே உரியது என்பதைக் கொண்டு உன்னிடம் கேட்கிறேன்; உன்னைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை; நீ பேருபகாரம் செய்பவன், வானங்களையும் பூமியையும் முன்மாதிரியின்றிப் படைத்தவன். மகத்துவமும் கண்ணியமும் உடையவனே, என்றும் உயிருள்ளவனே, நிலைநிறுத்துபவனே!", "இந்த மனிதர் அல்லாஹ்வின் மகத்தான பெயரைக் கொண்டு துஆ செய்தார் என்று நபி ﷺ அவர்கள் கூறினார்கள்.", "இந்தப் பெயரைக் கொண்டு செய்யப்படும் துஆ ஏற்கப்படுகிறது."),
        "dua_istiftah_kabira" to DuaText("அல்லாஹ் மிகப் பெரியவன், அதிகமான புகழ்", "அல்லாஹ் மிகப் பெரியவன்; அல்லாஹ்வுக்கே அதிகமான புகழ்; காலையிலும் மாலையிலும் அல்லாஹ் தூயவன்.", "தொழுகையைத் தொடங்கும்போது (தொடக்கப் புகழ்ச்சியின் ஒரு வடிவம்).", "நபி ﷺ அவர்கள் கூறினார்கள்: இதற்காக வானத்தின் வாசல்கள் திறக்கப்பட்டன."),
        "dua_istisqa_ibadak" to DuaText("உன் அடியார்களுக்கும் கால்நடைகளுக்கும் நீர் புகட்டு", "யா அல்லாஹ்! உன் அடியார்களுக்கும் உன் கால்நடைகளுக்கும் நீர் புகட்டுவாயாக, உன் கருணையைப் பரப்புவாயாக, இறந்துபோன உன் பூமிக்கு உயிரளிப்பாயாக.", "மழை வேண்டுதல் (இஸ்திஸ்கா).", "நபி ﷺ அவர்கள் மழைக்காக இந்த துஆவைச் செய்வார்கள்."),
        "dua_jahdil_bala" to DuaText("கடும் சோதனையிலிருந்து பாதுகாப்பு", "யா அல்லாஹ்! கடும் சோதனையிலிருந்தும், துர்பாக்கியம் வந்து சேர்வதிலிருந்தும், தீய விதியிலிருந்தும், எதிரிகள் மகிழ்வதிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன்.", "கடும் சோதனைகளிலிருந்தும் எதிரிகளின் மகிழ்ச்சியிலிருந்தும் பாதுகாப்பு.", "நபி ﷺ அவர்கள் இந்த நான்கிலிருந்தும் பாதுகாப்புத் தேடுவார்கள்."),
        "dua_jamarat" to DuaText("ஜமராத்தில் கல்லெறிதல்", "அல்லாஹ் மிகப் பெரியவன்.", "ஒவ்வொரு கல்லை எறியும்போதும்.", "நபி ﷺ அவர்கள் ஒவ்வொரு கல்லுடனும் தக்பீர் கூறினார்கள்; பின்னர் முதல் மற்றும் இரண்டாம் ஜமராவுக்குப் பிறகு கிப்லாவை முன்னோக்கி நீண்ட துஆ செய்தார்கள்."),
        "dua_jannah_nar" to DuaText("சுவர்க்கத்தைக் கேட்டல், நரகிலிருந்து பாதுகாப்பு", "யா அல்லாஹ்! உன்னிடம் சுவர்க்கத்தைக் கேட்கிறேன், நரகத்திலிருந்து உன்னிடம் பாதுகாப்புத் தேடுகிறேன்.", "அத்தஹிய்யாத்துக்குப் பிறகு அல்லது எந்த நேரத்திலும்.", "நபி ﷺ அவர்கள் கூறினார்கள்: எங்கள் துஆக்களும் இதைச் சுற்றியே அமைகின்றன."),
        "dua_jar_su" to DuaText("கெட்ட அண்டை வீட்டாரிலிருந்து பாதுகாப்பு", "யா அல்லாஹ்! நிரந்தர வசிப்பிடத்தில் கெட்ட அண்டை வீட்டாரிலிருந்து உன்னிடம் பாதுகாப்புத் தேடுகிறேன்; பயணத்தின் அண்டை வீட்டார் விலகிச் சென்றுவிடுவார்.", "கெட்ட அண்டை வீட்டாரிலிருந்து பாதுகாப்புக்காக.", "நபி ﷺ அவர்கள் இதிலிருந்து பாதுகாப்புத் தேடுமாறு கட்டளையிட்டார்கள்."),
        "dua_jiddi_wa_hazli" to DuaText("தீவிரமாகவும் விளையாட்டாகவும் செய்த பாவங்களை மன்னி", "யா அல்லாஹ்! நான் தீவிரமாகவும் விளையாட்டாகவும், தவறுதலாகவும் வேண்டுமென்றும் செய்த பாவங்களை மன்னிப்பாயாக — இவை அனைத்தும் என்னிடம் உள்ளன.", "அறிந்தும் அறியாமலும் செய்த எல்லா வகைப் பாவங்களுக்கும் மன்னிப்பு.", "நபி ﷺ அவர்களின் விரிவான இஸ்திஃக்ஃபார்."),
        "dua_ju_khiyanah" to DuaText("பசி மற்றும் மோசடியிலிருந்து பாதுகாப்பு", "யா அல்லாஹ்! பசியிலிருந்து உன்னிடம் பாதுகாப்புத் தேடுகிறேன், அது மிகக் கெட்ட தோழன்; மோசடியிலிருந்து உன்னிடம் பாதுகாப்புத் தேடுகிறேன், அது மிகக் கெட்ட அந்தரங்கத் துணை.", "பசி மற்றும் மோசடியிலிருந்து பாதுகாப்பு.", "நபி ﷺ அவர்களின் பாதுகாப்பு துஆ."),
        "dua_khayri_kullih" to DuaText("எல்லா நன்மையும், இப்போதும் பின்னரும்", "யா அல்லாஹ்! விரைவானதும் தாமதமானதும், நான் அறிந்ததும் அறியாததுமான எல்லா நன்மையையும் உன்னிடம் கேட்கிறேன்; விரைவானதும் தாமதமானதும், நான் அறிந்ததும் அறியாததுமான எல்லாத் தீமையிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன். யா அல்லாஹ்! சுவர்க்கத்தையும் அதன் பக்கம் நெருக்கமாக்கும் சொல்லையும் செயலையும் உன்னிடம் கேட்கிறேன்; நரகத்திலிருந்தும் அதன் பக்கம் நெருக்கமாக்கும் சொல்லிலிருந்தும் செயலிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன்.", "நபி ﷺ அவர்கள் ஆயிஷா (ரலி) அவர்களுக்குக் கற்றுக்கொடுத்த விரிவான துஆ (துஆவின் ஒரு பகுதி).", "எல்லா நன்மையையும் ஒன்றுசேர்க்கும் துஆ."),
        "dua_kufr_faqr" to DuaText("இறைமறுப்பு மற்றும் வறுமையிலிருந்து பாதுகாப்பு", "யா அல்லாஹ்! இறைமறுப்பிலிருந்தும் வறுமையிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன்; கப்ரின் வேதனையிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன். உன்னைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை.", "காலையிலும் மாலையிலும் மூன்று முறை.", "அபூ பக்ரா (ரலி) அவர்கள் நபி ﷺ அவர்கள் இதைக் கூறக் கேட்டார்கள்."),
        "dua_la_bas_tahur" to DuaText("நோயாளிக்கு ஆறுதல்: தூய்மைப்படுத்துதல்", "கவலை வேண்டாம்; இன்ஷா அல்லாஹ் (இந்நோய் பாவங்களிலிருந்து) தூய்மைப்படுத்துவதாகும்.", "நோயாளியை நலம் விசாரிக்கும்போது ஆறுதலுக்காக.", "நபி ﷺ அவர்கள் நோயாளியைச் சந்திக்கும்போது இதைக் கூறுவார்கள்."),
        "dua_la_mania" to DuaText("நீ கொடுப்பதை யாரும் தடுக்க முடியாது", "அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை; அவன் தனித்தவன், அவனுக்கு இணையில்லை. ஆட்சியும் புகழும் அவனுக்கே உரியன; அவன் எல்லாப் பொருட்கள் மீதும் ஆற்றலுடையவன். யா அல்லாஹ்! நீ கொடுப்பதைத் தடுப்பவர் யாருமில்லை, நீ தடுப்பதைக் கொடுப்பவர் யாருமில்லை; செல்வந்தரின் செல்வம் உன்னிடம் எந்தப் பயனும் அளிக்காது.", "ஃபர்ளு தொழுகையின் ஸலாமுக்குப் பிறகு.", "நபி ﷺ அவர்கள் ஒவ்வொரு ஃபர்ளு தொழுகைக்குப் பிறகும் இதைக் கூறுவார்கள்."),
        "dua_leaving_home_adilla" to DuaText("வழிகேட்டிலிருந்து பாதுகாப்பு", "யா அல்லாஹ்! நான் வழிதவறுவதிலிருந்தும் வழிதவறச் செய்யப்படுவதிலிருந்தும், நான் சறுகுவதிலிருந்தும் சறுகச் செய்யப்படுவதிலிருந்தும், நான் அநீதி இழைப்பதிலிருந்தும் எனக்கு அநீதி இழைக்கப்படுவதிலிருந்தும், நான் அறிவீனமாக நடப்பதிலிருந்தும் என்னிடம் அறிவீனமாக நடந்துகொள்ளப்படுவதிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன்.", "வீட்டை விட்டு வெளியேறும்போது — உம்மு ஸலமா (ரலி) அவர்கள் அறிவித்தது.", "நபி ﷺ அவர்கள் வீட்டை விட்டு வெளியேறும்போதெல்லாம் இதை ஓதுவார்கள்."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("முன்னும் பின்னும் செய்த பாவங்களை மன்னி", "யா அல்லாஹ்! நான் முன்பு செய்ததையும் பின்பு செய்ததையும், மறைவாகச் செய்ததையும் வெளிப்படையாகச் செய்ததையும், நான் வரம்பு மீறியதையும், என்னை விட நீ நன்கறிந்தவற்றையும் மன்னிப்பாயாக. நீயே முற்படுத்துபவன், நீயே பிற்படுத்துபவன்; உன்னைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை.", "அத்தஹிய்யாத் மற்றும் ஸலவாத்துக்குப் பிறகு, ஸலாமுக்கு முன்.", "நபி ﷺ அவர்கள் தொழுகையின் இறுதியில், அத்தஹிய்யாத்துக்கும் ஸலாமுக்கும் இடையே இதை ஓதுவார்கள்."),
        "dua_morning_blessing" to DuaText("காலை நேர அருட்கொடைகளுக்கு நன்றி", "யா அல்லாஹ்! இந்தக் காலையில் எனக்கோ உன் படைப்புகளில் எவருக்கோ கிடைத்த எந்த அருட்கொடையும் உன்னிடமிருந்து மட்டுமே; உனக்கு இணையில்லை. எனவே எல்லாப் புகழும் உனக்கே, எல்லா நன்றியும் உனக்கே.", "அல்லாஹ்வின் அருட்கொடைகளுக்காக நன்றி செலுத்தும் காலை திக்ர்."),
        "dua_morning_witness" to DuaText("காலை நேர ஏகத்துவச் சாட்சி", "யா அல்லாஹ்! நான் காலைப் பொழுதை அடைந்தேன்; நீயே அல்லாஹ், உன்னைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை, நீ தனித்தவன், உனக்கு இணையில்லை, முஹம்மது ﷺ உன் அடியாரும் தூதருமாவார்கள் என்பதற்கு உன்னையும், உன் அர்ஷைச் சுமப்பவர்களையும், உன் வானவர்களையும், உன் எல்லாப் படைப்புகளையும் சாட்சியாக்குகிறேன்.", "காலையில் இதை நான்கு முறை கூறுவதாக அறிவிப்பில் உள்ளது."),
        "dua_musarrifal_qulub" to DuaText("எங்கள் உள்ளங்களை உனக்குக் கீழ்ப்படிதலின் பக்கம் திருப்பு", "யா அல்லாஹ், உள்ளங்களைத் திருப்புபவனே! எங்கள் உள்ளங்களை உனக்குக் கீழ்ப்படிவதன் பக்கம் திருப்புவாயாக.", "உள்ளத்தைக் கீழ்ப்படிதலில் உறுதியாக வைப்பதற்கான துஆ.", "எல்லா மனிதர்களின் உள்ளங்களும் அளவற்ற அருளாளனின் இரு விரல்களுக்கு இடையே உள்ளன."),
        "dua_non_muslim_sneezes" to DuaText("முஸ்லிம் அல்லாதவர் தும்மும்போது", "அல்லாஹ் உங்களுக்கு நேர்வழி காட்டி, உங்கள் நிலையைச் சீராக்குவானாக.", "முஸ்லிம் அல்லாதவர் தும்மி 'அல்ஹம்துலில்லாஹ்' என்று கூறும்போது.", "நபி ﷺ அவர்கள் 'யர்ஹமுகல்லாஹ்' என்று கூறுவார்கள் என்ற எதிர்பார்ப்பில் யூதர்கள் அவர்கள் அருகில் தும்முவார்கள்; அப்போது அவர்கள் இதைக் கூறுவார்கள்."),
        "dua_praising_someone" to DuaText("ஒருவரைப் புகழும்போது", "இன்னாரை இவ்வாறு நான் கருதுகிறேன்; அல்லாஹ்வே அவரைக் கணக்கெடுப்பவன்; அல்லாஹ்வுக்கு முன் எவருடைய தூய்மைக்கும் நான் உத்தரவாதம் அளிப்பதில்லை.", "ஒருவரைப் புகழும்போது, மிகைப்படுத்துவதற்குப் பதிலாக.", "நபி ﷺ அவர்கள் புகழ்வதற்கான இந்த ஒழுங்கைக் கற்றுக்கொடுத்தார்கள்."),
        "dua_q_aqraba_rashada" to DuaText("என் இறைவன் என்னை இதை விட நேர்வழிக்கு அருகில் வழிநடத்தட்டும்", "என் இறைவன் இதை விட நேர்வழிக்கு நெருக்கமானதன் பக்கம் எனக்கு வழிகாட்டக்கூடும்.", "ஒரு காரியத்தில் சிறந்த வழியைத் தேடும்போது.", "மறந்துவிடும்போது இதைக் கூறுமாறு நபி ﷺ அவர்களுக்குக் கட்டளையிடப்பட்டது."),
        "dua_q_ashku_bathhi" to DuaText("அல்லாஹ்விடம் மட்டுமே முறையிடுகிறேன் (யஃகூப் அலை)", "என் துயரத்தையும் கவலையையும் அல்லாஹ்விடம் மட்டுமே முறையிடுகிறேன்.", "ஆழ்ந்த துயரத்திலும் பிரிவிலும்.", "யூஸுஃப் (அலை) அவர்களைப் பிரிந்த நிலையில் யஃகூப் (அலை) அவர்கள் இதைக் கூறினார்கள்."),
        "dua_q_do_not_make_us_trial" to DuaText("எங்களைச் சோதனையாக ஆக்காதே", "எங்கள் இறைவா! இறைமறுப்பாளர்களுக்கு எங்களைச் சோதனையாக ஆக்காதே; எங்களை மன்னிப்பாயாக, எங்கள் இறைவா! நிச்சயமாக நீயே மிகைத்தவன், ஞானமிக்கவன்.", "இப்ராஹீம் (அலை) அவர்களும் அவர்களுடைய தோழர்களும் செய்த துஆ."),
        "dua_q_hawariyyun" to DuaText("ஹவாரிய்யூன்களின் துஆ — எங்களைச் சாட்சியாளர்களுடன் பதிவு செய்", "எங்கள் இறைவா! நீ இறக்கியதை நாங்கள் நம்பினோம், தூதரைப் பின்பற்றினோம்; எனவே எங்களைச் சாட்சியாளர்களுடன் பதிவு செய்வாயாக.", "ஈமானிலும் தூதரைப் பின்பற்றுவதிலும் உறுதிக்காக.", "ஈஸா (அலை) அவர்களின் சீடர்களின் (ஹவாரிய்யூன்) துஆ."),
        "dua_q_iftah_baynana" to DuaText("எங்களுக்கிடையே தீர்ப்பளி (ஷுஐப் அலை)", "எங்கள் இறைவா! எங்களுக்கும் எங்கள் சமூகத்தாருக்கும் இடையே சத்தியத்துடன் தீர்ப்பளிப்பாயாக; நீயே தீர்ப்பளிப்போரில் மிகச் சிறந்தவன்.", "சத்தியத்துக்கும் அசத்தியத்துக்கும் இடையே தீர்ப்புக்காக.", "தம் சமூகத்தார் மறுத்தபோது ஷுஐப் (அலை) அவர்கள் செய்த துஆ."),
        "dua_q_ihkum_bil_haqq" to DuaText("என் இறைவா, சத்தியத்துடன் தீர்ப்பளி", "என் இறைவா! சத்தியத்துடன் தீர்ப்பளிப்பாயாக. எங்கள் இறைவன் அளவற்ற அருளாளன்; நீங்கள் வர்ணிப்பவற்றுக்கு எதிராக அவனிடமே உதவி தேடப்படுகிறது.", "பொய்கள் மற்றும் அவதூறுகளை எதிர்கொள்ளும்போது.", "நபி ﷺ அவர்களுக்குக் கற்றுக்கொடுக்கப்பட்ட துஆ."),
        "dua_q_khayrun_hafiza" to DuaText("அல்லாஹ்வே சிறந்த பாதுகாவலன்", "அல்லாஹ்வே சிறந்த பாதுகாவலன்; அவனே கருணையாளர்களில் மிகப் பெரும் கருணையாளன்.", "குழந்தைகளையோ அன்புக்குரியவர்களையோ பயணத்துக்கு அனுப்பும்போது.", "தம் மகனை அல்லாஹ்விடம் ஒப்படைக்கும்போது யஃகூப் (அலை) அவர்கள் இதைக் கூறினார்கள்."),
        "dua_q_la_akuna_zahiran" to DuaText("குற்றவாளிகளுக்கு ஒருபோதும் உதவியாளனாக மாட்டேன் (மூஸா அலை)", "என் இறைவா! நீ எனக்குச் செய்த அருளின் காரணமாக, நான் ஒருபோதும் குற்றவாளிகளுக்கு உதவியாளனாக இருக்க மாட்டேன்.", "அல்லாஹ்வின் அருட்கொடைகளுக்கு நன்றியும், அநியாயக்காரர்களுக்கு உதவாமல் இருப்பதற்கான உறுதிமொழியும்.", "தவ்பாவுக்குப் பிறகு மூஸா (அலை) அவர்கள் எடுத்த உறுதிமொழி."),
        "dua_q_la_tukhzini" to DuaText("என்னை இழிவுபடுத்தாதே (இப்ராஹீம் அலை)", "(மக்கள்) எழுப்பப்படும் நாளில் என்னை இழிவுபடுத்தாதே.", "மறுமை நாளின் இழிவிலிருந்து பாதுகாப்பாக இருக்க.", "மறுமைக்காக இப்ராஹீம் (அலை) அவர்கள் செய்த துஆ."),
        "dua_q_musa_li_akhi" to DuaText("என்னையும் என் சகோதரரையும் மன்னி (மூஸா அலை)", "என் இறைவா! என்னையும் என் சகோதரரையும் மன்னித்து, உன் கருணையில் எங்களை நுழைவிப்பாயாக; நீயே கருணையாளர்களில் மிகப் பெரும் கருணையாளன்.", "தமக்கும் தம் சகோதரர் அல்லது அன்புக்குரியவர்களுக்கும் மன்னிப்பு.", "ஹாரூன் (அலை) அவர்களுக்காக மூஸா (அலை) அவர்கள் செய்த துஆ."),
        "dua_q_muslimayni_laka" to DuaText("எங்களை உனக்குக் கீழ்ப்படிந்தவர்களாக ஆக்கு (இப்ராஹீம், இஸ்மாயீல் அலை)", "எங்கள் இறைவா! எங்கள் இருவரையும் உனக்குக் கீழ்ப்படிந்தவர்களாக ஆக்குவாயாக; எங்கள் சந்ததிகளிலிருந்தும் உனக்குக் கீழ்ப்படியும் ஒரு சமுதாயத்தை உருவாக்குவாயாக. எங்கள் வணக்க முறைகளை எங்களுக்குக் காட்டுவாயாக, எங்கள் தவ்பாவை ஏற்றுக்கொள்வாயாக; நிச்சயமாக நீயே தவ்பாவை ஏற்பவன், நிகரற்ற அன்புடையோன்.", "தமக்கும் தம் சந்ததிகளுக்கும் கீழ்ப்படிதலுக்கான துஆ.", "கஅபாவைக் கட்டும்போது செய்யப்பட்ட துஆ."),
        "dua_q_not_among_wrongdoers" to DuaText("என்னை அநியாயக்காரர்களுடன் சேர்க்காதே", "என் இறைவா! என்னை அநியாயக்காரக் கூட்டத்தாருடன் ஆக்காதே.", "அநியாயக்காரர்களை விட்டுத் தம்மை விலக்கி வைக்குமாறு அல்லாஹ்விடம் கேட்கும் துஆ."),
        "dua_q_nuh_unsurni" to DuaText("எனக்கு உதவு, அவர்கள் என்னைப் பொய்ப்பித்தனர் (நூஹ் அலை)", "என் இறைவா! எனக்கு உதவுவாயாக, அவர்கள் என்னைப் பொய்ப்பித்துவிட்டனர்.", "மக்கள் உங்களைப் பொய்ப்பித்து சத்தியத்தை மறுக்கும்போது.", "நூஹ் (அலை) அவர்களின் துஆ, அது ஏற்றுக்கொள்ளப்பட்டது."),
        "dua_q_sawa_as_sabil" to DuaText("எனக்கு நேரான பாதையைக் காட்டு (மூஸா அலை)", "என் இறைவன் எனக்கு நேரான பாதையைக் காட்டக்கூடும்.", "புதிய பயணம் அல்லது பழக்கமில்லாத பாதையில் செல்லும்போது.", "மத்யனை நோக்கித் திரும்பியபோது மூஸா (அலை) அவர்கள் இதைக் கூறினார்கள்."),
        "dua_q_ufawwidu_amri" to DuaText("என் காரியத்தை அல்லாஹ்விடம் ஒப்படைக்கிறேன்", "என் காரியத்தை அல்லாஹ்விடம் ஒப்படைக்கிறேன்; நிச்சயமாக அல்லாஹ் தன் அடியார்களை நன்கு பார்ப்பவன்.", "மக்கள் உங்களை எதிர்க்கும்போது, காரியத்தை அல்லாஹ்விடம் விட வேண்டியிருக்கும்போது.", "ஃபிர்அவ்னின் கூட்டத்தைச் சேர்ந்த முஃமினின் வார்த்தைகள்; பின்னர் அல்லாஹ் அவர்களின் தீய சூழ்ச்சிகளிலிருந்து அவரைப் பாதுகாத்தான்."),
        "dua_qadarullah" to DuaText("ஏதேனும் விரும்பாதது நிகழ்ந்தால்", "இது அல்லாஹ்வின் விதி; அவன் நாடியதைச் செய்தான்.", "விரும்பாத ஒன்று நிகழும்போது, 'அப்படிச் செய்திருந்தால்' என்று கூறுவதற்குப் பதிலாக.", "'அப்படிச் செய்திருந்தால்' என்பது ஷைத்தானின் வாசலைத் திறக்கிறது."),
        "dua_rabbi_ainni" to DuaText("என் இறைவா, எனக்கு உதவு, எனக்கு எதிராக அல்ல", "என் இறைவா! எனக்கு உதவுவாயாக, எனக்கு எதிராகப் பிறருக்கு உதவாதே; எனக்கு வெற்றி அளிப்பாயாக, எனக்கு எதிராகப் பிறருக்கு வெற்றி அளிக்காதே; எனக்காகத் திட்டமிடுவாயாக, எனக்கு எதிராகத் திட்டமிடாதே; எனக்கு நேர்வழி காட்டி, நேர்வழியை எனக்கு எளிதாக்குவாயாக; எனக்கு அநீதி இழைப்பவருக்கு எதிராக எனக்கு உதவுவாயாக.", "நபி ﷺ அவர்களின் விரிவான துஆ (தொடக்கப் பகுதி).", "மார்க்கத்திலும் உலகிலும் எல்லா உதவியையும் ஒன்றுசேர்க்கும் துஆ."),
        "dua_rabbighfir_tub_alayya" to DuaText("என்னை மன்னித்து என் தவ்பாவை ஏற்றுக்கொள்", "என் இறைவா! என்னை மன்னித்து, என் தவ்பாவை ஏற்றுக்கொள்வாயாக; நிச்சயமாக நீயே தவ்பாவை ஏற்பவன், நிகரற்ற அன்புடையோன்.", "ஒரே அமர்வில் நூறு முறை — நபி ﷺ அவர்களின் நடைமுறை.", "ஒரே அமர்வில் நபி ﷺ அவர்கள் இதை நூறு முறை கூறியதை ஸஹாபாக்கள் எண்ணினார்கள்."),
        "dua_rafiq_ala" to DuaText("மரணத் தருவாயில் உள்ளவரின் துஆ", "யா அல்லாஹ்! என்னை மன்னித்து, எனக்குக் கருணை காட்டி, மிக உயர்ந்த தோழர்களுடன் (அர்-ரஃபீக்குல் அஃலா) என்னைச் சேர்ப்பாயாக.", "நபி ﷺ அவர்களின் இறுதி துஆ — நோயாளி தமக்காகக் கூறுவது.", "நபி ﷺ அவர்கள் மறைவின்போது இந்த துஆவைச் செய்தார்கள்."),
        "dua_rahmataka_arju" to DuaText("உன் கருணையையே எதிர்பார்க்கிறேன்", "யா அல்லாஹ்! உன் கருணையையே எதிர்பார்க்கிறேன்; எனவே கண் இமைக்கும் நேரம் கூட என்னை என்னிடமே விட்டுவிடாதே; என் எல்லாக் காரியங்களையும் சீராக்குவாயாக. உன்னைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை.", "துன்பத்தில் உள்ளவரின் துஆ (தஃவாத்துல் மக்ரூப்).", "நபி ﷺ அவர்கள் இதைத் துன்பத்தில் உள்ளவரின் துஆ என்று கூறினார்கள்."),
        "dua_reply_ahl_kitab_salam" to DuaText("வேதக்காரர்களின் ஸலாமுக்குப் பதில்", "உங்கள் மீதும்.", "வேதக்காரர்கள் ஸலாம் கூறும்போது.", "நபி ﷺ அவர்களின் அறிவுறுத்தல்."),
        "dua_rising_ruku_mil" to DuaText("ருகூவுக்குப் பின் — வானங்கள் நிறையப் புகழ்", "எங்கள் இறைவா! எல்லாப் புகழும் உனக்கே — வானங்கள் நிறைய, பூமி நிறைய, அதன் பின் நீ நாடும் எல்லாவற்றின் நிறைய.", "ருகூவிலிருந்து எழுந்த பின், 'ரப்பனா லகல் ஹம்த்' உடன்.", "நபி ﷺ அவர்கள் ருகூவிலிருந்து எழும்போது இதைக் கூறுவார்கள்."),
        "dua_ruku_laka_raka_tu" to DuaText("ருகூவில் — உனக்காகக் குனிந்தேன்", "யா அல்லாஹ்! உனக்காகவே குனிந்தேன் (ருகூ செய்தேன்), உன்னையே நம்பினேன், உனக்கே கீழ்ப்படிந்தேன். என் செவிப்புலனும், பார்வையும், மூளையும், எலும்புகளும், நரம்புகளும் உனக்குப் பணிந்துவிட்டன.", "ருகூவில் (குறிப்பாக நஃபில் தொழுகைகளில்).", "நபி ﷺ அவர்கள் ருகூவில் இதை ஓதுவார்கள்."),
        "dua_ruku_sujood_subhanaka" to DuaText("எங்கள் இறைவா, நீ தூயவன் — என்னை மன்னி", "யா அல்லாஹ், எங்கள் இறைவா! உன் புகழுடன் நீ தூயவன். யா அல்லாஹ்! என்னை மன்னிப்பாயாக.", "ருகூவிலும் ஸஜ்தாவிலும்.", "ஆயிஷா (ரலி): நபி ﷺ அவர்கள் ருகூவிலும் ஸஜ்தாவிலும் இதை அதிகமாகக் கூறுவார்கள்."),
        "dua_seeing_clouds" to DuaText("கருமேகங்களைக் காணும்போது", "யா அல்லாஹ்! இதன் தீமையிலிருந்து உன்னிடம் பாதுகாப்புத் தேடுகிறேன்.", "வானில் கருமேகங்களைக் காணும்போது; மழை பெய்தால் 'அல்லாஹும்ம ஸய்யிபன் நாஃபிஆ' என்று கூறுங்கள்.", "மேகங்களைக் கண்டால் நபி ﷺ அவர்கள் செய்துகொண்டிருப்பதை விட்டுவிட்டு இந்த துஆவைச் செய்வார்கள்."),
        "dua_sharri_ma_amiltu" to DuaText("என் செயல்களின் தீமையிலிருந்து பாதுகாப்பு", "யா அல்லாஹ்! நான் செய்தவற்றின் தீமையிலிருந்தும், நான் செய்யாதவற்றின் தீமையிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன்.", "ஆயிஷா (ரலி) அவர்கள் அறிவித்தபடி நபி ﷺ அவர்களின் துஆ.", "செய்ததன் விளைவுகளிலிருந்தும் செய்யாமல் விட்டதன் விளைவுகளிலிருந்தும் பாதுகாப்பு."),
        "dua_sharri_sami" to DuaText("என் உறுப்புகளின் தீமையிலிருந்து பாதுகாப்பு", "யா அல்லாஹ்! என் செவியின் தீமையிலிருந்தும், என் பார்வையின் தீமையிலிருந்தும், என் நாவின் தீமையிலிருந்தும், என் உள்ளத்தின் தீமையிலிருந்தும், என் இச்சையின் தீமையிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன்.", "ஷகல் இப்னு ஹுமைத் (ரலி) அவர்களுக்குக் கற்றுக்கொடுக்கப்பட்டது.", "உறுப்புகளையும் மனதையும் பாவத்திலிருந்து பாதுகாக்கும் துஆ."),
        "dua_slaughtering" to DuaText("பிராணியை அறுக்கும்போது", "அல்லாஹ்வின் பெயரால், அல்லாஹ் மிகப் பெரியவன்.", "குர்பானி கொடுக்கும்போது அல்லது பிராணியை அறுக்கும்போது.", "நபி ﷺ அவர்கள் குர்பானியின்போது பிஸ்மில்லாஹ்வும் தக்பீரும் கூறினார்கள்."),
        "dua_sujood_laka_sajadtu" to DuaText("ஸஜ்தாவில் — உனக்கே ஸஜ்தா செய்தேன்", "யா அல்லாஹ்! உனக்கே ஸஜ்தா செய்தேன், உன்னையே நம்பினேன், உனக்கே கீழ்ப்படிந்தேன். என் முகம், அதைப் படைத்து, வடிவமைத்து, அதன் செவிப்புலனையும் பார்வையையும் வெளிப்படுத்தியவனுக்கு ஸஜ்தா செய்தது. படைப்பாளர்களில் மிகச் சிறந்தவனான அல்லாஹ் பாக்கியமிக்கவன்.", "ஸஜ்தாவில் (குறிப்பாக நஃபில் தொழுகைகளில்).", "நபி ﷺ அவர்கள் ஸஜ்தாவில் இதை ஓதுவார்கள்."),
        "dua_talqeen" to DuaText("மரணத் தருவாயில் உள்ளவருக்குத் தல்கீன்", "அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை.", "மரணத் தருவாயில் உள்ளவர் அருகில் கலிமாவை ஓதுங்கள் (அதைக் கூறுமாறு அவரை வற்புறுத்தாதீர்கள்).", "எவருடைய இறுதி வார்த்தை 'லா இலாஹ இல்லல்லாஹ்' ஆக இருக்கிறதோ அவர் சுவர்க்கத்தில் நுழைவார் (அபூ தாவூத் 3116)."),
        "dua_thabbitni_hadiyan" to DuaText("என்னை உறுதிப்படுத்தி, நேர்வழி பெற்றவனாகவும் காட்டுபவனாகவும் ஆக்கு", "யா அல்லாஹ்! என்னை உறுதிப்படுத்துவாயாக; என்னை நேர்வழி காட்டுபவனாகவும் நேர்வழி பெற்றவனாகவும் ஆக்குவாயாக.", "நபி ﷺ அவர்கள் ஜரீர் (ரலி) அவர்களுக்காக இந்த துஆவைச் செய்தார்கள் (உங்களுக்காக 'ஸப்பித்னீ' என்று கூறுங்கள்).", "ஜரீர் (ரலி) அவர்களுக்கான மூல துஆ 'ஸப்பித்ஹு' என்ற வார்த்தையுடன் உள்ளது."),
        "dua_traveller_sahar" to DuaText("அதிகாலைக்கு முன் பயணியின் துஆ", "அல்லாஹ்வை நாங்கள் புகழ்ந்ததையும், எங்கள் மீதான அவனுடைய நல்லருள்களையும் கேட்பவர் ஒருவர் கேட்டுவிட்டார் (பிறருக்கும் எடுத்துரைப்பார்). எங்கள் இறைவா! எங்களுடன் துணையாக இருந்து எங்கள் மீது அருள் புரிவாயாக — (இதை) நரகத்திலிருந்து அல்லாஹ்விடம் பாதுகாப்புத் தேடியவனாகக் (கூறுகிறேன்).", "பயணத்தில், அதிகாலைக்கு முன்.", "நபி ﷺ அவர்கள் பயணத்தின்போது அதிகாலைக்கு முன் இதைக் கூறுவார்கள்."),
        "dua_traveller_to_resident" to DuaText("பயணி தம் குடும்பத்தாருக்காகச் செய்யும் துஆ", "அடைக்கலப் பொருட்கள் ஒருபோதும் வீணாகாத அல்லாஹ்விடம் உங்களை ஒப்படைக்கிறேன்.", "பயணி தம் குடும்பத்தாரிடம் விடைபெறும்போது கூறுவது.", "குடும்பத்தாரின் பாதுகாப்பை அல்லாஹ்விடம் ஒப்படைத்தல்."),
        "dua_undressing" to DuaText("ஆடைகளைக் களையும்போது", "அல்லாஹ்வின் பெயரால்.", "ஆடைகளைக் களையும்போது (குளிக்க அல்லது ஆடை மாற்ற).", "இது ஜின்களின் பார்வைக்கும் மனிதனின் மறைவிடங்களுக்கும் இடையே திரையாகிறது."),
        "dua_vehicle_stumbles" to DuaText("வாகனம் சறுக்கினால்", "அல்லாஹ்வின் பெயரால்.", "வாகனம் அல்லது வாகனப் பிராணி சறுக்கினாலோ தடுமாறினாலோ, 'ஷைத்தான் அழியட்டும்' என்று கூறுவதற்குப் பதிலாக.", "பிஸ்மில்லாஹ் கூறுவது ஷைத்தானை ஈயின் அளவுக்குச் சிறுக்கச் செய்கிறது."),
        "dua_wedding_night" to DuaText("நிக்காஹுக்குப் பின் மனைவிக்காக", "யா அல்லாஹ்! இவளுடைய நன்மையையும், நீ இவளைப் படைத்த இயல்பின் நன்மையையும் உன்னிடம் கேட்கிறேன்; இவளுடைய தீமையிலிருந்தும், நீ இவளைப் படைத்த இயல்பின் தீமையிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன்.", "நிக்காஹுக்குப் பின், மனைவியின் நெற்றியில் கை வைத்து.", "நபி ﷺ அவர்களின் போதனை — திருமணத்தில் பரக்கத்."),
        "dua_zawwadakallah" to DuaText("பயணிக்கு: அல்லாஹ் உங்களுக்கு இறையச்சத்தைப் பயண உணவாக்கட்டும்", "அல்லாஹ் உங்களுக்கு இறையச்சத்தை (தக்வா) பயண உணவாக்குவானாக, உங்கள் பாவங்களை மன்னிப்பானாக, நீங்கள் எங்கிருந்தாலும் உங்களுக்கு நன்மையை எளிதாக்குவானாக.", "பயணியிடம் விடைபெறும்போது.", "பயணம் செல்லும் ஒருவருக்கு நபி ﷺ அவர்கள் இந்த துஆவைச் செய்தார்கள்.")
    )
}
